package pl.edu.mimuw;public class DynamicArray {    private int[] array;    private int arraySize;    private int size;    public DynamicArray() {        this.array = new int[1];        this.size = 0;        this.arraySize = 1;    }    public void add(int value) {        if (size == arraySize) {            int[] newArray = new int[arraySize * 2];            System.arraycopy(array, 0, newArray, 0, size);            array = newArray;            arraySize = arraySize * 2;        }        array[size] = value;        size++;    }    public int read(int index) {        return array[index];    }    public int getSize() {        return size;    }    public int pop() {        size--;        return array[size];    }}